171	export function parseArgs(argv: string[]): CliArgs {
172	  const out: CliArgs = {
173	    prompt: null,
174	    promptFiles: [],
175	    imagePath: null,
176	    provider: null,
177	    model: null,
178	    aspectRatio: null,
179	    aspectRatioSource: null,
180	    size: null,
181	    quality: null,
182	    imageSize: null,
183	    imageSizeSource: null,
184	    imageApiDialect: null,
185	    responseFormat: null,
186	    referenceImages: [],
187	    n: 1,
188	    batchFile: null,
189	    jobs: null,
190	    json: false,
191	    help: false,
192	  };
193	
194	  const positional: string[] = [];
195	
196	  const takeMany = (i: number): { items: string[]; next: number } => {
197	    const items: string[] = [];
198	    let j = i + 1;
199	    while (j < argv.length) {
200	      const v = argv[j]!;
201	      if (v.startsWith("-")) break;
202	      items.push(v);
203	      j++;
204	    }
205	    return { items, next: j - 1 };
206	  };
207	
208	  for (let i = 0; i < argv.length; i++) {
209	    const a = argv[i]!;
210	
211	    if (a === "--help" || a === "-h") {
212	      out.help = true;
213	      continue;
214	    }
215	
216	    if (a === "--json") {
217	      out.json = true;
218	      continue;
219	    }
220	
221	    if (a === "--prompt" || a === "-p") {
222	      const v = argv[++i];
223	      if (!v) throw new Error(`Missing value for ${a}`);
224	      out.prompt = v;
225	      continue;
226	    }
227	
228	    if (a === "--promptfiles") {
229	      const { items, next } = takeMany(i);
230	      if (items.length === 0) throw new Error("Missing files for --promptfiles");
231	      out.promptFiles.push(...items);
232	      i = next;
233	      continue;
234	    }
235	
236	    if (a === "--image") {
237	      const v = argv[++i];
238	      if (!v) throw new Error("Missing value for --image");
239	      out.imagePath = v;
240	      continue;
241	    }
242	
243	    if (a === "--batchfile") {
244	      const v = argv[++i];
245	      if (!v) throw new Error("Missing value for --batchfile");
246	      out.batchFile = v;
247	      continue;
248	    }
249	
250	    if (a === "--jobs") {
251	      const v = argv[++i];
252	      if (!v) throw new Error("Missing value for --jobs");
253	      out.jobs = parseInt(v, 10);
254	      if (isNaN(out.jobs) || out.jobs < 1) throw new Error(`Invalid worker count: ${v}`);
255	      continue;
256	    }
257	
258	    if (a === "--provider") {
259	      const v = argv[++i];
260	      if (
261	        v !== "google" &&
262	        v !== "openai" &&
263	        v !== "openrouter" &&
264	        v !== "dashscope" &&
265	        v !== "zai" &&
266	        v !== "minimax" &&
267	        v !== "replicate" &&
268	        v !== "jimeng" &&
269	        v !== "seedream" &&
270	        v !== "azure" &&
271	        v !== "codex-cli" &&
272	        v !== "agnes"
273	      ) {
274	        throw new Error(`Invalid provider: ${v}`);
275	      }
276	      out.provider = v;
277	      continue;
278	    }
279	
280	    if (a === "--model" || a === "-m") {
281	      const v = argv[++i];
282	      if (!v) throw new Error(`Missing value for ${a}`);
283	      out.model = v;
284	      continue;
285	    }
286	
287	    if (a === "--ar") {
288	      const v = argv[++i];
289	      if (!v) throw new Error("Missing value for --ar");
290	      out.aspectRatio = v;
291	      out.aspectRatioSource = "cli";
292	      continue;
293	    }
294	
295	    if (a === "--size") {
296	      const v = argv[++i];
297	      if (!v) throw new Error("Missing value for --size");
298	      out.size = v;
299	      continue;
300	    }
301	
302	    if (a === "--quality") {
303	      const v = argv[++i];
304	      if (v !== "normal" && v !== "2k") throw new Error(`Invalid quality: ${v}`);
305	      out.quality = v;
306	      continue;
307	    }
308	
309	    if (a === "--imageSize") {
310	      const v = argv[++i]?.toUpperCase();
311	      if (v !== "1K" && v !== "2K" && v !== "4K") throw new Error(`Invalid imageSize: ${v}`);
312	      out.imageSize = v;
313	      out.imageSizeSource = "cli";
314	      continue;
315	    }
316	
317	    if (a === "--imageApiDialect") {
318	      const v = argv[++i];
319	      if (v !== "openai-native" && v !== "ratio-metadata") {
320	        throw new Error(`Invalid imageApiDialect: ${v}`);
321	      }
322	      out.imageApiDialect = v;
323	      continue;
324	    }
325	
326	    if (a === "--response-format") {
327	      const v = argv[++i];
328	      if (v !== "file" && v !== "url") throw new Error(`Invalid response-format: ${v}`);
329	      out.responseFormat = v;
330	      continue;
331	    }
332	
333	    if (a === "--ref" || a === "--reference") {
334	      const { items, next } = takeMany(i);
335	      if (items.length === 0) throw new Error(`Missing files for ${a}`);
336	      out.referenceImages.push(...items);
337	      i = next;
338	      continue;
339	    }
340	
341	    if (a === "--n") {
342	      const v = argv[++i];
343	      if (!v) throw new Error("Missing value for --n");
344	      out.n = parseInt(v, 10);
345	      if (isNaN(out.n) || out.n < 1) throw new Error(`Invalid count: ${v}`);
346	      continue;
347	    }
348	
349	    if (a.startsWith("-")) {
350	      throw new Error(`Unknown option: ${a}`);
351	    }
352	
353	    positional.push(a);
354	  }
355	
356	  if (!out.prompt && out.promptFiles.length === 0 && positional.length > 0) {
357	    out.prompt = positional.join(" ");
358	  }
359	
360	  return out;
361	}
