363	async function loadEnvFile(p: string): Promise<Record<string, string>> {
364	  try {
365	    const content = await readFile(p, "utf8");
366	    const env: Record<string, string> = {};
367	    for (const line of content.split("\n")) {
368	      const trimmed = line.trim();
369	      if (!trimmed || trimmed.startsWith("#")) continue;
370	      const idx = trimmed.indexOf("=");
371	      if (idx === -1) continue;
372	      const key = trimmed.slice(0, idx).trim();
373	      let val = trimmed.slice(idx + 1).trim();
374	      if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
375	        val = val.slice(1, -1);
376	      }
377	      env[key] = val;
378	    }
379	    return env;
380	  } catch {
381	    return {};
382	  }
383	}
