385	async function loadEnv(): Promise<void> {
386	  const home = homedir();
387	  const cwd = process.cwd();
388	
389	  const homeEnv = await loadEnvFile(path.join(home, ".baoyu-skills", ".env"));
390	  const cwdEnv = await loadEnvFile(path.join(cwd, ".baoyu-skills", ".env"));
391	
392	  for (const [k, v] of Object.entries(homeEnv)) {
393	    if (!process.env[k]) process.env[k] = v;
394	  }
395	  for (const [k, v] of Object.entries(cwdEnv)) {
396	    if (!process.env[k]) process.env[k] = v;
397	  }
398	}
