530	export function parseOpenAIImageApiDialect(
531	  value: string | undefined | null
532	): OpenAIImageApiDialect | null {
533	  if (!value) return null;
534	  const normalized = value.replace(/['"]/g, "").trim();
535	  if (normalized === "openai-native" || normalized === "ratio-metadata") return normalized;
536	  throw new Error(`Invalid OpenAI image API dialect: ${value}`);
537	}
