566	async function migrateLegacyExtendConfig(cwd: string, home: string): Promise<void> {
567	  for (const { current, legacy } of getExtendConfigPathPairs(cwd, home)) {
568	    const [hasCurrent, hasLegacy] = await Promise.all([exists(current), exists(legacy)]);
569	    if (hasCurrent || !hasLegacy) continue;
570	    await mkdir(path.dirname(current), { recursive: true });
571	    await rename(legacy, current);
572	  }
573	}
