575	export async function loadExtendConfig(
576	  cwd = process.cwd(),
577	  home = homedir(),
578	): Promise<Partial<ExtendConfig>> {
579	  await migrateLegacyExtendConfig(cwd, home);
580	
581	  const paths = getExtendConfigPathPairs(cwd, home).map(({ current }) => current);
582	
