718	export function detectProvider(args: CliArgs): Provider {
719	  if (
720	    args.referenceImages.length > 0 &&
721	    args.provider &&
722	    args.provider !== "google" &&
723	    args.provider !== "openai" &&
724	    args.provider !== "azure" &&
725	    args.provider !== "openrouter" &&
726	    args.provider !== "replicate" &&
727	    args.provider !== "seedream" &&
728	    args.provider !== "minimax" &&
729	    args.provider !== "dashscope" &&
730	    args.provider !== "codex-cli" &&
731	    args.provider !== "agnes"
732	  ) {
733	    throw new Error(
734	      "Reference images require a ref-capable provider. Use --provider google (Gemini multimodal), --provider openai (GPT Image edits), --provider azure (Azure OpenAI), --provider openrouter (OpenRouter multimodal), --provider replicate, --provider dashscope with a wan2.7 image model, --provider seedream for supported Seedream models, --provider minimax for MiniMax subject-reference workflows, --provider codex-cli (Codex image_gen with references), or --provider agnes (Agnes Image)."
735	    );
736	  }
737	
738	  if (args.provider) return args.provider;
739	
740	  const hasGoogle = !!(process.env.GOOGLE_API_KEY || process.env.GEMINI_API_KEY);
741	  const hasAzure = !!(process.env.AZURE_OPENAI_API_KEY && process.env.AZURE_OPENAI_BASE_URL);
742	  const hasOpenai = !!process.env.OPENAI_API_KEY;
743	  const hasOpenrouter = !!process.env.OPENROUTER_API_KEY;
744	  const hasDashscope = !!process.env.DASHSCOPE_API_KEY;
745	  const hasZai = !!(process.env.ZAI_API_KEY || process.env.BIGMODEL_API_KEY);
746	  const hasMinimax = !!process.env.MINIMAX_API_KEY;
747	  const hasReplicate = !!process.env.REPLICATE_API_TOKEN;
748	  const hasJimeng = !!(process.env.JIMENG_ACCESS_KEY_ID && process.env.JIMENG_SECRET_ACCESS_KEY);
749	  const hasSeedream = !!process.env.ARK_API_KEY;
750	  const hasAgnes = !!process.env.AGNES_API_KEY;
751	  const modelProvider = inferProviderFromModel(args.model);
752	
753	  if (modelProvider === "seedream") {
754	    if (!hasSeedream) {
755	      throw new Error("Model looks like a Volcengine ARK image model, but ARK_API_KEY is not set.");
756	    }
757	    return "seedream";
758	  }
759	
760	  if (modelProvider === "minimax") {
761	    if (!hasMinimax) {
762	      throw new Error("Model looks like a MiniMax image model, but MINIMAX_API_KEY is not set.");
763	    }
764	    return "minimax";
765	  }
766	
767	  if (modelProvider === "zai") {
768	    if (!hasZai) {
769	      throw new Error("Model looks like a Z.AI image model, but ZAI_API_KEY is not set.");
770	    }
771	    return "zai";
772	  }
773	
774	  if (modelProvider === "agnes") {
775	    if (!hasAgnes) {
776	      throw new Error("Model looks like an Agnes image model, but AGNES_API_KEY is not set.");
777	    }
778	    return "agnes";
779	  }
780	
781	  if (args.referenceImages.length > 0) {
782	    if (hasGoogle) return "google";
783	    if (hasOpenai) return "openai";
784	    if (hasAzure) return "azure";
785	    if (hasOpenrouter) return "openrouter";
786	    if (hasReplicate) return "replicate";
787	    if (hasSeedream) return "seedream";
788	    if (hasMinimax) return "minimax";
789	    if (hasAgnes) return "agnes";
790	    throw new Error(
791	      "Reference images require Google, OpenAI, Azure, OpenRouter, Replicate, supported Seedream models, MiniMax, or Agnes. Set GOOGLE_API_KEY/GEMINI_API_KEY, OPENAI_API_KEY, AZURE_OPENAI_API_KEY+AZURE_OPENAI_BASE_URL, OPENROUTER_API_KEY, REPLICATE_API_TOKEN, ARK_API_KEY, MINIMAX_API_KEY, or AGNES_API_KEY, or remove --ref."
792	    );
793	  }
794	
795	  const available = [
796	    hasGoogle && "google",
797	    hasOpenai && "openai",
798	    hasAzure && "azure",
799	    hasOpenrouter && "openrouter",
800	    hasDashscope && "dashscope",
801	    hasZai && "zai",
802	    hasMinimax && "minimax",
803	    hasReplicate && "replicate",
804	    hasJimeng && "jimeng",
805	    hasSeedream && "seedream",
806	    hasAgnes && "agnes",
807	  ].filter(Boolean) as Provider[];
808	
809	  if (available.length === 1) return available[0]!;
810	  if (available.length > 1) return available[0]!;
811	
812	  throw new Error(
813	    "No API key found. Set GOOGLE_API_KEY, GEMINI_API_KEY, OPENAI_API_KEY, AZURE_OPENAI_API_KEY+AZURE_OPENAI_BASE_URL, OPENROUTER_API_KEY, DASHSCOPE_API_KEY, ZAI_API_KEY, MINIMAX_API_KEY, REPLICATE_API_TOKEN, JIMENG keys, ARK_API_KEY, or AGNES_API_KEY.\n" +
814	      "Create ~/.baoyu-skills/.env or <cwd>/.baoyu-skills/.env with your keys."
815	  );
816	}
