1056	async function generatePreparedTask(task: PreparedTask): Promise<TaskResult> {
1057	  console.error(`Using ${task.provider} / ${task.model} for ${task.id}`);
1058	  console.error(
1059	    `Switch model: --model <id> | EXTEND.md default_model.${task.provider} | env ${task.provider.toUpperCase()}_IMAGE_MODEL`
1060	  );
1061	
1062	  let attempts = 0;
1063	  while (attempts < MAX_ATTEMPTS) {
1064	    attempts += 1;
1065	    try {
1066	      const imageData = await task.providerModule.generateImage(task.prompt, task.model, task.args);
1067	      await writeImage(task.outputPath, imageData);
1068	      return {
1069	        id: task.id,
1070	        provider: task.provider,
1071	        model: task.model,
1072	        outputPath: task.outputPath,
1073	        success: true,
1074	        attempts,
1075	        error: null,
1076	      };
1077	    } catch (error) {
1078	      const message = error instanceof Error ? error.message : String(error);
1079	      const canRetry = attempts < MAX_ATTEMPTS && isRetryableGenerationError(error);
1080	      if (canRetry) {
1081	        console.error(`[${task.id}] Attempt ${attempts}/${MAX_ATTEMPTS} failed, retrying...`);
1082	        continue;
1083	      }
1084	      return {
1085	        id: task.id,
1086	        provider: task.provider,
1087	        model: task.model,
1088	        outputPath: task.outputPath,
1089	        success: false,
1090	        attempts,
1091	        error: message,
1092	      };
1093	    }
1094	  }
1095	
1096	  return {
1097	    id: task.id,
1098	    provider: task.provider,
1099	    model: task.model,
1100	    outputPath: task.outputPath,
1101	    success: false,
1102	    attempts: MAX_ATTEMPTS,
