1137	async function runBatchTasks(
1138	  tasks: PreparedTask[],
1139	  jobs: number | null,
1140	  extendConfig: Partial<ExtendConfig>
1141	): Promise<TaskResult[]> {
1142	  if (tasks.length === 1) {
1143	    return [await generatePreparedTask(tasks[0]!)];
1144	  }
1145	
1146	  const maxWorkers = getConfiguredMaxWorkers(extendConfig);
1147	  const providerRateLimits = getConfiguredProviderRateLimits(extendConfig);
1148	  const acquireProvider = createProviderGate(providerRateLimits);
1149	  const workerCount = getWorkerCount(tasks.length, jobs, maxWorkers);
1150	  console.error(`Batch mode: ${tasks.length} tasks, ${workerCount} workers, parallel mode enabled.`);
1151	  for (const provider of ["replicate", "google", "openai", "openrouter", "dashscope", "zai", "minimax", "jimeng", "seedream", "azure", "codex-cli", "agnes"] as Provider[]) {
1152	    const limit = providerRateLimits[provider];
1153	    console.error(`- ${provider}: concurrency=${limit.concurrency}, startIntervalMs=${limit.startIntervalMs}`);
1154	  }
1155	
1156	  let nextIndex = 0;
1157	  const results: TaskResult[] = new Array(tasks.length);
1158	
1159	  const worker = async (): Promise<void> => {
1160	    while (true) {
1161	      const currentIndex = nextIndex;
1162	      nextIndex += 1;
1163	      if (currentIndex >= tasks.length) return;
1164	
1165	      const task = tasks[currentIndex]!;
1166	      const release = await acquireProvider(task.provider);
1167	      try {
1168	        results[currentIndex] = await generatePreparedTask(task);
1169	      } finally {
1170	        release();
1171	      }
1172	    }
1173	  };
1174	
1175	  await Promise.all(Array.from({ length: workerCount }, () => worker()));
1176	  return results;
1177	}
