188	function findKnownRatioKey(ar: string, candidates: string[], tolerance = 0.02): string | null {
189	  const targetRatio = getRatioValue(ar);
190	  if (targetRatio == null) return null;
191	
192	  let bestKey: string | null = null;
193	  let bestDiff = Infinity;
194	
195	  for (const candidate of candidates) {
196	    const candidateRatio = getRatioValue(candidate);
197	    if (candidateRatio == null) continue;
198	    const diff = Math.abs(candidateRatio - targetRatio);
199	    if (diff < bestDiff) {
200	      bestDiff = diff;
201	      bestKey = candidate;
202	    }
203	  }
204	
205	  return bestDiff <= tolerance ? bestKey : null;
206	}
