216	function fitToPixelBudget(
217	  width: number,
218	  height: number,
219	  minPixels: number,
220	  maxPixels: number,
221	): { width: number; height: number } {
222	  let nextWidth = width;
223	  let nextHeight = height;
224	  let pixels = nextWidth * nextHeight;
225	
226	  if (pixels > maxPixels) {
227	    const scale = Math.sqrt(maxPixels / pixels);
228	    nextWidth *= scale;
229	    nextHeight *= scale;
230	  } else if (pixels < minPixels) {
231	    const scale = Math.sqrt(minPixels / pixels);
232	    nextWidth *= scale;
233	    nextHeight *= scale;
234	  }
235	
236	  let roundedWidth = roundToStep(nextWidth);
237	  let roundedHeight = roundToStep(nextHeight);
238	  pixels = roundedWidth * roundedHeight;
239	
240	  while (pixels > maxPixels && (roundedWidth > SIZE_STEP || roundedHeight > SIZE_STEP)) {
241	    if (roundedWidth >= roundedHeight && roundedWidth > SIZE_STEP) {
242	      roundedWidth -= SIZE_STEP;
243	    } else if (roundedHeight > SIZE_STEP) {
244	      roundedHeight -= SIZE_STEP;
245	    } else {
246	      break;
247	    }
248	    pixels = roundedWidth * roundedHeight;
249	  }
250	
251	  while (pixels < minPixels) {
252	    if (roundedWidth <= roundedHeight) {
253	      roundedWidth += SIZE_STEP;
254	    } else {
255	      roundedHeight += SIZE_STEP;
256	    }
257	    pixels = roundedWidth * roundedHeight;
258	  }
259	
260	  return { width: roundedWidth, height: roundedHeight };
261	}
