345	export function getWan27SizeFromAspectRatio(
346	  ar: string | null,
347	  quality: CliArgs["quality"],
348	  maxPixels: number,
349	): string {
350	  const normalizedQuality = normalizeQuality(quality);
351	  const targetPixels = Math.min(WAN27_TARGET_PIXELS[normalizedQuality], maxPixels);
352	
353	  if (!ar) {
354	    const side = roundToStep(Math.sqrt(targetPixels));
355	    return formatSize(side, side);
356	  }
357	
358	  const parsed = parseAspectRatio(ar);
359	  if (!parsed) {
360	    const side = roundToStep(Math.sqrt(targetPixels));
361	    return formatSize(side, side);
362	  }
363	
364	  const ratio = parsed.width / parsed.height;
365	  if (ratio < 1 / 8 || ratio > 8) {
366	    throw new Error(
367	      `DashScope wan2.7 image models support aspect ratios in [1:8, 8:1]. Received "${ar}".`
368	    );
369	  }
370	
371	  const rawWidth = Math.sqrt(targetPixels * ratio);
372	  const rawHeight = Math.sqrt(targetPixels / ratio);
373	  const fitted = fitToPixelBudget(
374	    rawWidth,
375	    rawHeight,
376	    MIN_WAN27_TOTAL_PIXELS,
377	    maxPixels,
378	  );
379	  const bounded = clampWan27DerivedSizeToRatioBounds(fitted);
380	
381	  return formatSize(bounded.width, bounded.height);
382	}
