384	function validateWan27Size(size: string, maxPixels: number, model: string): string {
385	  const normalized = normalizeSize(size);
386	  const parsed = validateSizeFormat(normalized);
387	  const totalPixels = parsed.width * parsed.height;
388	  if (totalPixels < MIN_WAN27_TOTAL_PIXELS || totalPixels > maxPixels) {
389	    const limit = maxPixels === MAX_WAN27_PRO_T2I_PIXELS ? "4096*4096" : "2048*2048";
390	    throw new Error(
391	      `DashScope ${model} requires total pixels between 768*768 and ${limit} ` +
392	      `for the current request. Received ${normalized} (${totalPixels} pixels).`
393	    );
394	  }
395	  const ratio = parsed.width / parsed.height;
396	  if (ratio < 1 / 8 || ratio > 8) {
397	    throw new Error(
398	      `DashScope wan2.7 image models support aspect ratios in [1:8, 8:1]. ` +
399	      `Received ${normalized} (ratio ${ratio.toFixed(3)}).`
400	    );
401	  }
402	  return normalized;
403	}
