405	function getQwenFixedSizeFromAspectRatio(ar: string | null, quality: CliArgs["quality"]): string {
406	  if (quality === "normal") {
407	    console.warn(
408	      "DashScope qwen-image-max/plus/image models use fixed output sizes; --quality normal does not change the generated resolution."
409	    );
410	  }
411	
412	  if (!ar) return QWEN_FIXED_SPEC.defaultSize;
413	
414	  const ratioKey = findKnownRatioKey(ar, Object.keys(QWEN_FIXED_SIZES_BY_RATIO));
415	  if (!ratioKey) {
416	    throw new Error(
417	      `DashScope model supports only fixed ratios ${Object.keys(QWEN_FIXED_SIZES_BY_RATIO).join(", ")}. ` +
418	      `For custom ratios like "${ar}", use --model qwen-image-2.0-pro.`
419	    );
420	  }
421	
422	  return QWEN_FIXED_SIZES_BY_RATIO[ratioKey]!;
423	}
