425	function validateSizeFormat(size: string): { width: number; height: number } {
426	  const parsed = parseSize(size);
427	  if (!parsed) {
428	    throw new Error(`Invalid DashScope size "${size}". Expected <width>x<height> or <width>*<height>.`);
429	  }
430	  return parsed;
431	}
432	
433	function validateQwen2Size(size: string): string {
434	  const normalized = normalizeSize(size);
435	  const parsed = validateSizeFormat(normalized);
436	  const totalPixels = parsed.width * parsed.height;
437	  if (totalPixels < MIN_QWEN_2_TOTAL_PIXELS || totalPixels > MAX_QWEN_2_TOTAL_PIXELS) {
438	    throw new Error(
439	      `DashScope qwen-image-2.0* models require total pixels between ${MIN_QWEN_2_TOTAL_PIXELS} ` +
440	      `and ${MAX_QWEN_2_TOTAL_PIXELS}. Received ${normalized} (${totalPixels} pixels).`
441	    );
442	  }
443	  return normalized;
444	}
445	
446	function validateQwenFixedSize(size: string): string {
447	  const normalized = normalizeSize(size);
448	  validateSizeFormat(normalized);
449	  if (!QWEN_FIXED_SIZES.includes(normalized)) {
450	    throw new Error(
451	      `DashScope qwen-image-max/plus/image models support only these sizes: ${QWEN_FIXED_SIZES.join(", ")}. ` +
452	      `Received ${normalized}.`
453	    );
454	  }
455	  return normalized;
456	}
