458	export function resolveSizeForModel(
459	  model: string,
460	  args: Pick<CliArgs, "size" | "aspectRatio" | "quality"> & { referenceImages?: string[] },
461	): string {
462	  const spec = getModelSpec(model);
463	  const referenceCount = args.referenceImages?.length ?? 0;
464	
465	  if (spec.family === "wan27") {
466	    const maxPixels = getWan27MaxPixels(model, referenceCount > 0);
467	    if (args.size) return validateWan27Size(args.size, maxPixels, model);
468	    return getWan27SizeFromAspectRatio(args.aspectRatio, args.quality, maxPixels);
469	  }
470	
471	  if (args.size) {
472	    if (spec.family === "qwen2") return validateQwen2Size(args.size);
473	    if (spec.family === "qwenFixed") return validateQwenFixedSize(args.size);
474	    validateSizeFormat(args.size);
475	    return normalizeSize(args.size);
476	  }
477	
478	  if (spec.family === "qwen2") {
479	    return getQwen2SizeFromAspectRatio(args.aspectRatio, args.quality);
480	  }
481	
482	  if (spec.family === "qwenFixed") {
483	    return getQwenFixedSizeFromAspectRatio(args.aspectRatio, args.quality);
484	  }
485	
486	  return getSizeFromAspectRatio(args.aspectRatio, args.quality);
487	}
