26	function resolveEndpoint(query: Record<string, string>): {
27	  url: string;
28	  host: string;
29	  canonicalUri: string;
30	} {
31	  let baseUrl: URL;
32	  try {
33	    baseUrl = new URL(getBaseUrl());
34	  } catch {
35	    throw new Error(`Invalid JIMENG_BASE_URL: ${getBaseUrl()}`);
36	  }
37	
38	  baseUrl.search = "";
39	  for (const [key, value] of Object.entries(query).sort(([a], [b]) => a.localeCompare(b))) {
40	    baseUrl.searchParams.set(key, value);
41	  }
42	
43	  return {
44	    url: baseUrl.toString(),
45	    host: baseUrl.host,
46	    canonicalUri: baseUrl.pathname || "/",
47	  };
48	}
