50	/**
51	 * Volcengine HMAC-SHA256 signature generation
52	 * Following the official documentation at:
53	 * https://www.volcengine.com/docs/85621/1817045
54	 */
55	function generateSignature(
56	  method: string,
57	  query: Record<string, string>,
58	  headers: Record<string, string>,
59	  body: string,
60	  accessKey: string,
61	  secretKey: string,
62	  region: string,
63	  service: string,
64	  canonicalUri: string
65	): string {
66	  // 1. Create canonical request
67	  // Sort query parameters alphabetically
68	  const sortedQuery = Object.entries(query)
69	    .sort(([a], [b]) => a.localeCompare(b))
70	    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
71	    .join("&");
72	
73	  // Sort headers alphabetically and create canonical headers
74	  const sortedHeaders = Object.entries(headers)
75	    .sort(([a], [b]) => a.localeCompare(b))
76	    .map(([k, v]) => `${k.toLowerCase()}:${v.trim()}\n`)
77	    .join("");
78	
79	  const signedHeaders = Object.keys(headers)
80	    .sort()
81	    .map(k => k.toLowerCase())
82	    .join(";");
83	
84	  const hashedPayload = crypto.createHash("sha256").update(body, "utf8").digest("hex");
85	
86	  const canonicalRequest = [
87	    method,
88	    canonicalUri,
89	    sortedQuery,
90	    sortedHeaders,
91	    signedHeaders,
92	    hashedPayload,
93	  ].join("\n");
94	
95	  const hashedCanonicalRequest = crypto
96	    .createHash("sha256")
97	    .update(canonicalRequest, "utf8")
98	    .digest("hex");
99	
100	  // 2. Create string to sign
101	  const algorithm = "HMAC-SHA256";
102	  const timestamp = headers["X-Date"] || headers["x-date"];
103	  if (!timestamp) {
104	    throw new Error("Jimeng signature generation requires an X-Date header.");
105	  }
106	  const dateStamp = timestamp.slice(0, 8);
107	
108	  const credentialScope = `${dateStamp}/${region}/${service}/request`;
109	
110	  const stringToSign = [
111	    algorithm,
112	    timestamp,
113	    credentialScope,
114	    hashedCanonicalRequest,
115	  ].join("\n");
116	
117	  // 3. Calculate signature
118	  const kDate = crypto
119	    .createHmac("sha256", secretKey)
120	    .update(dateStamp)
121	    .digest();
122	
123	  const kRegion = crypto.createHmac("sha256", kDate).update(region).digest();
124	  const kService = crypto.createHmac("sha256", kRegion).update(service).digest();
125	  const kSigning = crypto.createHmac("sha256", kService).update("request").digest();
126	
127	  const signature = crypto
128	    .createHmac("sha256", kSigning)
129	    .update(stringToSign)
130	    .digest("hex");
131	
132	  // 4. Create authorization header
133	  return `${algorithm} Credential=${accessKey}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;
134	}
