136	/**
137	 * Parse aspect ratio string like "16:9", "1:1", "4:3" into width and height
138	 */
139	function parseAspectRatio(ar: string): { width: number; height: number } | null {
140	  const match = ar.match(/^(\d+(?:\.\d+)?):(\d+(?:\.\d+)?)$/);
141	  if (!match) return null;
142	  const w = parseFloat(match[1]!);
143	  const h = parseFloat(match[2]!);
144	  if (w <= 0 || h <= 0) return null;
145	  return { width: w, height: h };
146	}
