148	/**
149	 * Supported size presets for different quality levels
150	 * Based on Volcengine Jimeng documentation
151	 */
152	const SIZE_PRESETS: Record<string, Record<string, string>> = {
153	  normal: {
154	    "1:1": "1024x1024",
155	    "4:3": "1360x1020",
156	    "16:9": "1536x864",
157	    "3:2": "1440x960",
158	    "21:9": "1920x824",
159	  },
160	  "2k": {
161	    "1:1": "2048x2048",
162	    "4:3": "2304x1728",
163	    "16:9": "2560x1440",
164	    "3:2": "2496x1664",
165	    "21:9": "3024x1296",
166	  },
167	  "4k": {
168	    "1:1": "4096x4096",
169	    "4:3": "4694x3520",
170	    "16:9": "5404x3040",
171	    "3:2": "4992x3328",
172	    "21:9": "6198x2656",
173	  },
174	};
175	
176	function normalizeDimensions(value: string): string | null {
177	  const match = value.trim().match(/^(\d+)\s*[xX*]\s*(\d+)$/);
178	  if (!match) return null;
179	  return `${match[1]}x${match[2]}`;
180	}
181	
182	function getClosestPresetSize(ar: string | null, qualityLevel: JimengSizePreset): string {
183	  const presets = SIZE_PRESETS[qualityLevel];
184	  const defaultSize = presets["1:1"]!;
185	
186	  if (!ar) return defaultSize;
187	
188	  const parsed = parseAspectRatio(ar);
189	  if (!parsed) return defaultSize;
190	
191	  const targetRatio = parsed.width / parsed.height;
192	  let bestMatch = defaultSize;
193	  let bestDiff = Infinity;
194	
195	  for (const [ratio, size] of Object.entries(presets)) {
196	    const [w, h] = ratio.split(":").map(Number);
197	    const presetRatio = w / h;
198	    const diff = Math.abs(presetRatio - targetRatio);
199	    if (diff < bestDiff) {
200	      bestDiff = diff;
201	      bestMatch = size;
202	    }
203	  }
204	
205	  return bestMatch;
206	}
207	
208	function normalizeImageSizePreset(imageSize: string, ar: string | null): string | null {
209	  const preset = imageSize.trim().toUpperCase();
210	  if (preset === "1K") return getClosestPresetSize(ar, "normal");
211	  if (preset === "2K") return getClosestPresetSize(ar, "2k");
212	  if (preset === "4K") return getClosestPresetSize(ar, "4k");
213	  return normalizeDimensions(imageSize);
214	}
215	
216	function getImageSize(ar: string | null, quality: CliArgs["quality"], imageSize?: string | null): string {
217	  if (imageSize) {
218	    const normalizedSize = normalizeImageSizePreset(imageSize, ar);
219	    if (normalizedSize) return normalizedSize;
220	  }
221	
222	  // Default to 2K quality if not specified
223	  const qualityLevel: JimengSizePreset = quality === "normal" ? "normal" : "2k";
224	  return getClosestPresetSize(ar, qualityLevel);
225	}
