227	/**
228	 * Step 1: Submit async task to Volcengine Jimeng API
229	 */
230	async function submitTask(
231	  prompt: string,
232	  model: string,
233	  size: string,
234	  accessKey: string,
235	  secretKey: string,
236	  region: string
237	): Promise<string> {
238	  // Query parameters for submit endpoint
239	  const query = {
240	    Action: "CVSync2AsyncSubmitTask",
241	    Version: "2022-08-31",
242	  };
243	  const endpoint = resolveEndpoint(query);
244	
245	  // Request body - Jimeng API expects width/height as separate integers
246	  const [width, height] = size.split("x").map(Number);
247	  const bodyObj = {
248	    req_key: model,
249	    prompt,
250	    // Use separate width and height parameters instead of size string
251	    width: width,
252	    height: height,
253	    // Optional: seed for reproducibility
254	    // seed: Math.floor(Math.random() * 999999),
255	  };
256	
257	  const body = JSON.stringify(bodyObj);
258	
259	  // Headers
260	  const timestampHeader = new Date().toISOString().replace(/[:\-]|\.\d{3}/g, "");
261	  const headers = {
262	    "Content-Type": "application/json",
263	    "X-Date": timestampHeader,
264	    "Host": endpoint.host,
265	  };
266	
267	  // Generate signature
268	  const authorization = generateSignature(
269	    "POST",
270	    query,
271	    headers,
272	    body,
273	    accessKey,
274	    secretKey,
275	    region,
276	    "cv",
277	    endpoint.canonicalUri
278	  );
279	
280	  console.error(`Submitting task to Jimeng (${model})...`, { width, height });
281	
282	  const res = await fetch(endpoint.url, {
283	    method: "POST",
284	    headers: {
285	      ...headers,
286	      "Authorization": authorization,
287	    },
288	    body,
289	  });
290	
291	  if (!res.ok) {
292	    const err = await res.text();
293	    throw new Error(`Jimeng API submit error (${res.status}): ${err}`);
294	  }
295	
296	  const result = (await res.json()) as {
297	    code?: number;
298	    message?: string;
299	    data?: {
300	      task_id?: string;
301	    };
302	  };
303	
304	  // Volcengine API returns code 10000 for success
305	  if (result.code !== 10000 || !result.data?.task_id) {
306	    console.error("Submit response:", JSON.stringify(result, null, 2));
307	    throw new Error(`Failed to submit task: ${result.message || "Unknown error"}`);
308	  }
309	
310	  return result.data.task_id;
311	}
312	
313	/**
314	 * Step 2: Poll for task result
315	 * Returns image data directly as Uint8Array
316	 */
317	async function pollForResult(
318	  taskId: string,
319	  model: string,
320	  accessKey: string,
321	  secretKey: string,
322	  region: string
323	): Promise<Uint8Array> {
324	  const maxAttempts = 60;
325	  const pollIntervalMs = 2000;
326	
327	  for (let attempt = 0; attempt < maxAttempts; attempt++) {
328	    // Query parameters for result endpoint
329	    const query = {
330	      Action: "CVSync2AsyncGetResult",
331	      Version: "2022-08-31",
332	    };
333	    const endpoint = resolveEndpoint(query);
334	
335	    // Request body - include req_key and task_id
336	    const bodyObj = {
337	      req_key: model,
338	      task_id: taskId,
339	    };
340	
341	    const body = JSON.stringify(bodyObj);
342	
343	    // Headers
344	    const timestampHeader = new Date().toISOString().replace(/[:\-]|\.\d{3}/g, "");
345	    const headers = {
346	      "Content-Type": "application/json",
347	      "X-Date": timestampHeader,
348	      "Host": endpoint.host,
349	    };
350	
351	    // Generate signature
352	    const authorization = generateSignature(
353	      "POST",
354	      query,
355	      headers,
356	      body,
357	      accessKey,
358	      secretKey,
359	      region,
360	      "cv",
361	      endpoint.canonicalUri
362	    );
363	
364	    const res = await fetch(endpoint.url, {
365	      method: "POST",
366	      headers: {
367	        ...headers,
368	        "Authorization": authorization,
369	      },
370	      body,
371	    });
372	
373	    if (!res.ok) {
374	      const err = await res.text();
375	      throw new Error(`Jimeng API poll error (${res.status}): ${err}`);
376	    }
377	
378	    const result = (await res.json()) as {
379	      code?: number;
380	      message?: string;
381	      data?: {
382	        status?: string;
383	        image_urls?: string[];
384	        binary_data_base64?: string[];
385	      };
386	    };
387	
388	    // Volcengine API returns code 10000 for success
389	    if (result.code === 10000 && result.data) {
390	      const { status, image_urls, binary_data_base64 } = result.data;
391	
392	      // Check for base64 image data (preferred by Jimeng)
393	      if (binary_data_base64 && binary_data_base64.length > 0) {
394	        console.error("Image received as base64 data");
395	        const base64Data = binary_data_base64[0]!;
396	        // Convert base64 to Uint8Array
397	        const binaryString = Buffer.from(base64Data, "base64").toString("binary");
398	        const bytes = new Uint8Array(binaryString.length);
399	        for (let i = 0; i < binaryString.length; i++) {
400	          bytes[i] = binaryString.charCodeAt(i);
401	        }
402	        return bytes;
403	      }
404	
405	      // Fallback to URL format
406	      if (status === "done" && image_urls && image_urls.length > 0) {
407	        // Download from URL
408	        console.error(`Downloading image from ${image_urls[0]}...`);
409	        const imgRes = await fetch(image_urls[0]!);
410	        if (!imgRes.ok) {
411	          throw new Error(`Failed to download image from ${image_urls[0]}`);
412	        }
413	        const buffer = await imgRes.arrayBuffer();
414	        return new Uint8Array(buffer);
415	      }
416	
417	      if (status === "in_queue" || status === "generating") {
418	        console.error(`Task status: ${status} (${attempt + 1}/${maxAttempts})`);
419	        await new Promise(resolve => setTimeout(resolve, pollIntervalMs));
420	        continue;
421	      }
422	
423	      if (status === "fail") {
424	        throw new Error(`Jimeng task failed: ${result.message || "Generation failed"}`);
425	      }
426	    }
427	
428	    console.error("Poll response:", JSON.stringify(result, null, 2));
429	    throw new Error(`Unexpected response during polling: ${result.message || "Unknown error"}`);
430	  }
431	
432	  throw new Error("Task timeout: image generation took too long");
433	}
434	
435	export async function generateImage(
436	  prompt: string,
437	  model: string,
438	  args: CliArgs
439	): Promise<Uint8Array> {
440	  if (args.referenceImages.length > 0) {
441	    throw new Error(
442	      "Jimeng does not support reference images. Use --provider google, openai, openrouter, or replicate."
443	    );
444	  }
445	
446	  const accessKey = getAccessKey();
447	  const secretKey = getSecretKey();
448	  const region = getRegion();
449	
450	  if (!accessKey || !secretKey) {
451	    throw new Error(
452	      "JIMENG_ACCESS_KEY_ID and JIMENG_SECRET_ACCESS_KEY are required. " +
453	      "Get your credentials from https://console.volcengine.com/iam/keymanage"
454	    );
455	  }
456	
457	  const size = getImageSize(args.aspectRatio, args.quality, args.imageSize);
458	
459	  // Step 1: Submit task
460	  const taskId = await submitTask(prompt, model, size, accessKey, secretKey, region);
461	
462	  // Step 2: Poll for result (returns image data directly)
463	  const imageData = await pollForResult(taskId, model, accessKey, secretKey, region);
464	
465	  console.error("Image generation complete!");
466	  return imageData;
467	}
