144	  if (family === "seedream5") return "2K";
145	  if (family === "seedream45") return "2K";
146	  if (family === "seedream40") return args.quality === "normal" ? "1K" : "2K";
147	  if (family === "seedream30") return args.quality === "2k" ? "2048x2048" : "1024x1024";
148	  return "2K";
149	}
