151	export function resolveSeedreamSize(model: string, args: CliArgs): string {
152	  assertSupportedModel(model);
153	  const family = getModelFamily(model);
154	  const requested = args.size || args.imageSize || null;
155	  const normalized = requested ? normalizeSizeValue(requested) : null;
156	
157	  if (!normalized) {
158	    return getDefaultSeedreamSize(model, args);
159	  }
160	
161	  if (family === "seedream30") {
162	    const pixelSize = normalizePixelSize(normalized);
163	    if (!pixelSize) {
164	      throw new Error("Seedream 3.0 only supports explicit WxH sizes such as 1024x1024.");
165	    }
166	    return pixelSize;
167	  }
168	
169	  if (family === "seedream5") {
170	    if (normalized === "4K" || normalized === "1K" || normalized === "adaptive") {
171	      throw new Error("Seedream 5.0 only supports 2K, 3K, or explicit WxH sizes.");
172	    }
173	    return normalized;
174	  }
175	
176	  if (family === "seedream45") {
177	    if (normalized === "1K" || normalized === "3K" || normalized === "adaptive") {
178	      throw new Error("Seedream 4.5 only supports 2K, 4K, or explicit WxH sizes.");
179	    }
180	    return normalized;
181	  }
182	
183	  if (family === "seedream40") {
184	    if (normalized === "3K" || normalized === "adaptive") {
185	      throw new Error("Seedream 4.0 only supports 1K, 2K, 4K, or explicit WxH sizes.");
186	    }
187	    return normalized;
188	  }
189	
190	  if (normalized === "adaptive") {
191	    throw new Error("Adaptive size is not supported by Seedream image generation.");
192	  }
193	
194	  if (normalized === "1K" || normalized === "3K" || normalized === "4K") {
195	    throw new Error(
196	      "Unknown Seedream model ID. Use a documented model ID or pass an explicit WxH size instead of preset imageSize."
197	    );
198	  }
199	
200	  return normalized;
201	}
