45	  const ratio = parsed ? parsed.width / parsed.height : 1;
46	
47	  if (!parsed || Math.abs(ratio - 1) < 0.1) {
48	    const edge = quality === "2k" ? 2048 : 1024;
49	    return `${edge}x${edge}`;
50	  }
51	
52	  const targetLongEdge = quality === "2k" ? 2048 : 1024;
53	  let width: number;
54	  let height: number;
55	
56	  if (ratio > 1) {
57	    width = targetLongEdge;
58	    height = roundToMultiple(width / ratio, 16);
59	  } else {
60	    height = targetLongEdge;
61	    width = roundToMultiple(height * ratio, 16);
62	  }
63	
64	  while (width * height < 655_360) {
65	    if (ratio > 1) {
66	      width += 16;
67	      height = roundToMultiple(width / ratio, 16);
68	    } else {
69	      height += 16;
