245	      throw new Error(`Invalid gpt-image-2 aspect ratio: ${args.aspectRatio}`);
246	    }
247	    const ratio = parsed.width / parsed.height;
248	    if (Math.max(ratio, 1 / ratio) > 3) {
249	      throw new Error("gpt-image-2 aspect ratio must not exceed 3:1.");
250	    }
251	  }
252	
253	  if (!args.size) return;
254	
255	  const parsedSize = parsePixelSize(args.size);
256	  if (!parsedSize) {
257	    throw new Error(`Invalid gpt-image-2 --size: ${args.size}. Expected <width>x<height>.`);
258	  }
259	
260	  const { width, height } = parsedSize;
261	  const totalPixels = width * height;
262	  const ratio = Math.max(width, height) / Math.min(width, height);
263	
264	  if (Math.max(width, height) > 3840) {
265	    throw new Error("gpt-image-2 --size maximum edge length must be 3840px or less.");
266	  }
267	  if (width % 16 !== 0 || height % 16 !== 0) {
268	    throw new Error("gpt-image-2 --size width and height must both be multiples of 16px.");
269	  }
270	  if (ratio > 3) {
271	    throw new Error("gpt-image-2 --size long edge to short edge ratio must not exceed 3:1.");
272	  }
273	  if (totalPixels < 655_360 || totalPixels > 8_294_400) {
274	    throw new Error("gpt-image-2 --size total pixels must be between 655,360 and 8,294,400.");
275	  }
276	}
