320	async function generateWithChatCompletions(
321	  baseURL: string,
322	  apiKey: string,
323	  prompt: string,
324	  model: string
325	): Promise<Uint8Array> {
326	  const res = await fetch(`${baseURL}/chat/completions`, {
327	    method: "POST",
328	    headers: {
329	      "Content-Type": "application/json",
330	      Authorization: `Bearer ${apiKey}`,
331	    },
332	    body: JSON.stringify({
333	      model,
334	      messages: [{ role: "user", content: prompt }],
335	    }),
336	  });
337	
338	  if (!res.ok) {
339	    const err = await res.text();
340	    throw new Error(`OpenAI API error: ${err}`);
341	  }
342	
343	  const result = (await res.json()) as { choices: Array<{ message: { content: string } }> };
344	  const content = result.choices[0]?.message?.content ?? "";
345	
346	  const match = content.match(/data:image\/[^;]+;base64,([A-Za-z0-9+/=]+)/);
347	  if (match) {
348	    return Uint8Array.from(Buffer.from(match[1]!, "base64"));
349	  }
350	
351	  throw new Error("No image found in chat completions response");
352	}
