377	async function generateWithOpenAIEdits(
378	  baseURL: string,
379	  apiKey: string,
380	  prompt: string,
381	  model: string,
382	  size: string,
383	  referenceImages: string[],
384	  quality: CliArgs["quality"]
385	): Promise<Uint8Array> {
386	  const form = new FormData();
387	  form.append("model", model);
388	  form.append("prompt", prompt);
389	  form.append("size", size);
390	
391	  const openAIQuality = getOpenAIQuality(model, quality);
392	  if (openAIQuality && openAIQuality !== "standard" && openAIQuality !== "hd") {
393	    form.append("quality", openAIQuality);
394	  }
395	
396	  for (const refPath of referenceImages) {
397	    const bytes = await readFile(refPath);
398	    const filename = path.basename(refPath);
399	    const mimeType = getMimeType(filename);
400	    const blob = new Blob([bytes], { type: mimeType });
401	    form.append("image[]", blob, filename);
402	  }
403	
404	  const res = await fetch(`${baseURL}/images/edits`, {
405	    method: "POST",
406	    headers: {
407	      Authorization: `Bearer ${apiKey}`,
408	    },
409	    body: form,
410	  });
411	
412	  if (!res.ok) {
413	    const err = await res.text();
414	    throw new Error(`OpenAI edits API error: ${err}`);
415	  }
416	
417	  const result = (await res.json()) as OpenAIImageResponse;
418	  return extractImageFromResponse(result);
419	}
