421	export function getMimeType(filename: string): string {
422	  const ext = path.extname(filename).toLowerCase();
423	  if (ext === ".jpg" || ext === ".jpeg") return "image/jpeg";
424	  if (ext === ".webp") return "image/webp";
425	  if (ext === ".gif") return "image/gif";
426	  return "image/png";
427	}
