429	export async function extractImageFromResponse(result: OpenAIImageResponse): Promise<Uint8Array> {
430	  const img = result.data[0];
431	
432	  if (img?.b64_json) {
433	    return Uint8Array.from(Buffer.from(img.b64_json, "base64"));
434	  }
435	
436	  if (img?.url) {
437	    const imgRes = await fetch(img.url);
438	    if (!imgRes.ok) throw new Error("Failed to download image");
439	    const buf = await imgRes.arrayBuffer();
440	    return new Uint8Array(buf);
441	  }
442	
443	  throw new Error("No image in response");
444	}
