154	export function parseAspectRatio(ar: string): { width: number; height: number } | null {
155	  const match = ar.match(/^(\d+(?:\.\d+)?):(\d+(?:\.\d+)?)$/);
156	  if (!match) return null;
157	  const w = parseFloat(match[1]!);
158	  const h = parseFloat(match[2]!);
159	  if (w <= 0 || h <= 0) return null;
160	  return { width: w, height: h };
161	}
