167	export function parseSize(size: string): { width: number; height: number } | null {
168	  const match = normalizeSize(size).match(/^(\d+)\*(\d+)$/);
169	  if (!match) return null;
170	  const width = Number(match[1]);
171	  const height = Number(match[2]);
172	  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) {
173	    return null;
174	  }
175	  return { width, height };
176	}
