208	function roundToStep(value: number): number {
209	  return Math.max(SIZE_STEP, Math.round(value / SIZE_STEP) * SIZE_STEP);
210	}
211	
212	function floorToStep(value: number): number {
213	  return Math.max(SIZE_STEP, Math.floor(value / SIZE_STEP) * SIZE_STEP);
214	}
