263	function clampWan27DerivedSizeToRatioBounds(
264	  size: { width: number; height: number },
265	): { width: number; height: number } {
266	  let { width, height } = size;
267	  const ratio = width / height;
268	
269	  if (ratio > 8) {
270	    width = floorToStep(height * 8);
271	  } else if (ratio < 1 / 8) {
272	    height = floorToStep(width * 8);
273	  }
274	
275	  return { width, height };
276	}
