278	export function getSizeFromAspectRatio(ar: string | null, quality: CliArgs["quality"]): string {
279	  const normalizedQuality = normalizeQuality(quality);
280	  const sizes = normalizedQuality === "2k" ? LEGACY_STANDARD_SIZES_2K : LEGACY_STANDARD_SIZES;
281	  const defaultSize = normalizedQuality === "2k" ? "1536*1536" : "1024*1024";
282	
283	  if (!ar) return defaultSize;
284	
285	  const parsed = parseAspectRatio(ar);
286	  if (!parsed) return defaultSize;
287	
288	  const targetRatio = parsed.width / parsed.height;
289	  let best = defaultSize;
290	  let bestDiff = Infinity;
291	
292	  for (const [width, height] of sizes) {
293	    const diff = Math.abs(width / height - targetRatio);
294	    if (diff < bestDiff) {
295	      bestDiff = diff;
296	      best = formatSize(width, height);
297	    }
298	  }
299	
300	  return best;
301	}
