303	export function getQwen2SizeFromAspectRatio(ar: string | null, quality: CliArgs["quality"]): string {
304	  const normalizedQuality = normalizeQuality(quality);
305	
306	  if (!ar) {
307	    return QWEN_2_RECOMMENDED["1:1"][normalizedQuality];
308	  }
309	
310	  const recommendedRatio = findKnownRatioKey(ar, Object.keys(QWEN_2_RECOMMENDED));
311	  if (recommendedRatio) {
312	    return QWEN_2_RECOMMENDED[recommendedRatio][normalizedQuality];
313	  }
314	
315	  const parsed = parseAspectRatio(ar);
316	  if (!parsed) {
317	    return QWEN_2_RECOMMENDED["1:1"][normalizedQuality];
318	  }
319	
320	  const targetRatio = parsed.width / parsed.height;
321	  const targetPixels = QWEN_2_TARGET_PIXELS[normalizedQuality];
322	  const rawWidth = Math.sqrt(targetPixels * targetRatio);
323	  const rawHeight = Math.sqrt(targetPixels / targetRatio);
324	  const fitted = fitToPixelBudget(
325	    rawWidth,
326	    rawHeight,
327	    MIN_QWEN_2_TOTAL_PIXELS,
328	    MAX_QWEN_2_TOTAL_PIXELS,
329	  );
330	
331	  return formatSize(fitted.width, fitted.height);
332	}
