489	function buildParameters(
490	  family: DashScopeModelFamily,
491	  size: string,
492	): Record<string, unknown> {
493	  if (family === "wan27") {
494	    return {
495	      size,
496	      n: 1,
497	      watermark: false,
498	    };
499	  }
500	
501	  const parameters: Record<string, unknown> = {
502	    prompt_extend: false,
503	    size,
504	  };
505	
506	  if (family === "qwen2" || family === "qwenFixed") {
507	    parameters.watermark = false;
508	    parameters.negative_prompt = QWEN_NEGATIVE_PROMPT;
509	  }
510	
511	  return parameters;
512	}
