514	type DashScopeResponse = {
515	  output?: {
516	    result_image?: string;
517	    choices?: Array<{
518	      message?: {
519	        content?: Array<{ image?: string }>;
520	      };
521	    }>;
522	  };
523	};
524	
525	async function extractImageFromResponse(result: DashScopeResponse): Promise<Uint8Array> {
526	  let imageData: string | null = null;
527	
528	  if (result.output?.result_image) {
529	    imageData = result.output.result_image;
530	  } else if (result.output?.choices?.[0]?.message?.content) {
531	    const content = result.output.choices[0].message.content;
532	    for (const item of content) {
533	      if (item.image) {
534	        imageData = item.image;
535	        break;
536	      }
537	    }
538	  }
539	
540	  if (!imageData) {
541	    console.error("Response:", JSON.stringify(result, null, 2));
542	    throw new Error("No image in response");
543	  }
544	
545	  if (imageData.startsWith("http://") || imageData.startsWith("https://")) {
546	    const imgRes = await fetch(imageData);
547	    if (!imgRes.ok) throw new Error("Failed to download image");
548	    const buf = await imgRes.arrayBuffer();
549	    return new Uint8Array(buf);
550	  }
551	
552	  return Uint8Array.from(Buffer.from(imageData, "base64"));
553	}
554	
555	export async function generateImage(
556	  prompt: string,
557	  model: string,
558	  args: CliArgs
559	): Promise<Uint8Array> {
560	  const apiKey = getApiKey();
561	  if (!apiKey) throw new Error("DASHSCOPE_API_KEY is required");
562	
563	  const spec = getModelSpec(model);
564	
565	  if (args.referenceImages.length > 0 && spec.family !== "wan27") {
566	    throw new Error(
567	      "Reference images are not supported with this DashScope model. Use a wan2.7 image model (--model wan2.7-image-pro or wan2.7-image), or switch to --provider google with a Gemini multimodal model."
568	    );
569	  }
570	
571	  if (args.referenceImages.length > WAN27_MAX_REFERENCE_IMAGES) {
572	    throw new Error(
573	      `DashScope wan2.7 image models accept at most ${WAN27_MAX_REFERENCE_IMAGES} reference images. Received ${args.referenceImages.length}.`
574	    );
575	  }
576	
577	  if (spec.family === "wan27" && args.n !== 1) {
578	    throw new Error(
579	      "DashScope wan2.7 image models in baoyu-image-gen support exactly one output image per request (extra images would be billed but discarded). Remove --n or use --n 1."
580	    );
581	  }
582	
583	  const size = resolveSizeForModel(model, args);
584	  const url = `${getBaseUrl()}/api/v1/services/aigc/multimodal-generation/generation`;
585	
586	  const content: Array<Record<string, unknown>> = [];
587	  if (spec.family === "wan27" && args.referenceImages.length > 0) {
588	    for (const refPath of args.referenceImages) {
589	      content.push({ image: await loadReferenceImage(refPath) });
590	    }
591	  }
592	  content.push({ text: prompt });
593	
594	  const body = {
595	    model,
596	    input: {
597	      messages: [
598	        {
599	          role: "user",
600	          content,
601	        },
602	      ],
603	    },
604	    parameters: buildParameters(spec.family, size),
605	  };
606	
607	  console.log(`Generating image with DashScope (${model})...`, { family: spec.family, size });
608	
609	  const res = await fetch(url, {
610	    method: "POST",
611	    headers: {
612	      "Content-Type": "application/json",
613	      Authorization: `Bearer ${apiKey}`,
614	    },
615	    body: JSON.stringify(body),
616	  });
617	
618	  if (!res.ok) {
619	    const err = await res.text();
620	    throw new Error(`DashScope API error (${res.status}): ${err}`);
621	  }
622	
623	  const result = await res.json() as DashScopeResponse;
624	  return extractImageFromResponse(result);
625	}
