405	export function parseSimpleYaml(yaml: string): Partial<ExtendConfig> {
406	  const config: Partial<ExtendConfig> = {};
407	  const lines = yaml.split("\n");
408	  let currentKey: string | null = null;
409	  let currentProvider: Provider | null = null;
410	
411	  for (const line of lines) {
412	    const trimmed = line.trim();
413	    const indent = line.match(/^\s*/)?.[0].length ?? 0;
414	    if (!trimmed || trimmed.startsWith("#")) continue;
415	
416	    if (trimmed.includes(":") && !trimmed.startsWith("-")) {
417	      const colonIdx = trimmed.indexOf(":");
418	      const key = trimmed.slice(0, colonIdx).trim();
419	      let value = trimmed.slice(colonIdx + 1).trim();
420	
421	      if (value === "null" || value === "") {
422	        value = "null";
423	      }
424	
425	      if (key === "version") {
426	        config.version = value === "null" ? 1 : parseInt(value, 10);
427	      } else if (key === "default_provider") {
428	        config.default_provider = value === "null" ? null : (value as Provider);
429	      } else if (key === "default_quality") {
430	        config.default_quality = value === "null" ? null : value as "normal" | "2k";
431	      } else if (key === "default_aspect_ratio") {
432	        const cleaned = value.replace(/['"]/g, "");
433	        config.default_aspect_ratio = cleaned === "null" ? null : cleaned;
434	      } else if (key === "default_image_size") {
435	        config.default_image_size = value === "null" ? null : value as "1K" | "2K" | "4K";
436	      } else if (key === "default_image_api_dialect") {
437	        config.default_image_api_dialect =
438	          value === "null" ? null : parseOpenAIImageApiDialect(value);
439	      } else if (key === "default_model") {
440	        config.default_model = {
441	          google: null,
442	          openai: null,
443	          openrouter: null,
444	          dashscope: null,
445	          zai: null,
446	          minimax: null,
447	          replicate: null,
448	          jimeng: null,
449	          seedream: null,
450	          azure: null,
451	          "codex-cli": null,
452	          agnes: null,
453	        };
454	        currentKey = "default_model";
455	        currentProvider = null;
456	      } else if (key === "batch") {
457	        config.batch = {};
458	        currentKey = "batch";
459	        currentProvider = null;
460	      } else if (currentKey === "batch" && indent >= 2 && key === "max_workers") {
461	        config.batch ??= {};
462	        config.batch.max_workers = value === "null" ? null : parseInt(value, 10);
463	      } else if (currentKey === "batch" && indent >= 2 && key === "provider_limits") {
464	        config.batch ??= {};
465	        config.batch.provider_limits ??= {};
466	        currentKey = "provider_limits";
467	        currentProvider = null;
468	      } else if (
469	        currentKey === "provider_limits" &&
470	        indent >= 4 &&
471	        (
472	          key === "google" ||
473	          key === "openai" ||
474	          key === "openrouter" ||
475	          key === "dashscope" ||
476	          key === "zai" ||
477	          key === "minimax" ||
478	          key === "replicate" ||
479	          key === "jimeng" ||
480	          key === "seedream" ||
481	          key === "azure" ||
482	          key === "codex-cli" ||
483	          key === "agnes"
484	        )
485	      ) {
486	        config.batch ??= {};
487	        config.batch.provider_limits ??= {};
488	        config.batch.provider_limits[key] ??= {};
489	        currentProvider = key;
490	      } else if (
491	        currentKey === "default_model" &&
492	        (
493	          key === "google" ||
494	          key === "openai" ||
495	          key === "openrouter" ||
496	          key === "dashscope" ||
497	          key === "zai" ||
498	          key === "minimax" ||
499	          key === "replicate" ||
500	          key === "jimeng" ||
501	          key === "seedream" ||
502	          key === "azure" ||
503	          key === "codex-cli" ||
504	          key === "agnes"
505	        )
506	      ) {
507	        const cleaned = value.replace(/['"]/g, "");
508	        config.default_model![key] = cleaned === "null" ? null : cleaned;
509	      } else if (
510	        currentKey === "provider_limits" &&
511	        currentProvider &&
512	        indent >= 6 &&
513	        (key === "concurrency" || key === "start_interval_ms")
514	      ) {
515	        config.batch ??= {};
516	        config.batch.provider_limits ??= {};
517	        const providerLimit = (config.batch.provider_limits[currentProvider] ??= {});
518	        if (key === "concurrency") {
519	          providerLimit.concurrency = value === "null" ? null : parseInt(value, 10);
520	        } else {
521	          providerLimit.start_interval_ms = value === "null" ? null : parseInt(value, 10);
522	        }
523	      }
524	    }
525	  }
526	
527	  return config;
528	}
