1107	function createProviderGate(providerRateLimits: Record<Provider, ProviderRateLimit>) {
1108	  const state = new Map<Provider, { active: number; lastStartedAt: number }>();
1109	
1110	  return async function acquire(provider: Provider): Promise<() => void> {
1111	    const limit = providerRateLimits[provider];
1112	    while (true) {
1113	      const current = state.get(provider) ?? { active: 0, lastStartedAt: 0 };
1114	      const now = Date.now();
1115	      const enoughCapacity = current.active < limit.concurrency;
1116	      const enoughGap = now - current.lastStartedAt >= limit.startIntervalMs;
1117	      if (enoughCapacity && enoughGap) {
1118	        state.set(provider, { active: current.active + 1, lastStartedAt: now });
1119	        return () => {
1120	          const latest = state.get(provider) ?? { active: 1, lastStartedAt: now };
1121	          state.set(provider, {
1122	            active: Math.max(0, latest.active - 1),
1123	            lastStartedAt: latest.lastStartedAt,
1124	          });
1125	        };
1126	      }
1127	      await new Promise((resolve) => setTimeout(resolve, POLL_WAIT_MS));
1128	    }
1129	  };
1130	}
