1132	export function getWorkerCount(taskCount: number, jobs: number | null, maxWorkers: number): number {
1133	  const requested = jobs ?? Math.min(taskCount, maxWorkers);
1134	  return Math.max(1, Math.min(requested, taskCount, maxWorkers));
1135	}
