1181	  const failureCount = results.length - successCount;
1182	
1183	  console.error("");
1184	  console.error("Batch generation summary:");
1185	  console.error(`- Total: ${results.length}`);
1186	  console.error(`- Succeeded: ${successCount}`);
1187	  console.error(`- Failed: ${failureCount}`);
1188	
1189	  if (failureCount > 0) {
1190	    console.error("Failure reasons:");
1191	    for (const result of results.filter((item) => !item.success)) {
1192	      console.error(`- ${result.id}: ${result.error}`);
1193	    }
1194	  }
1195	}
